// ENG-2478 regression: advanced search's type filter dropdown must be unchanged by the split.
const MODAL = ".dg-node-search-modal";
const BUTTON = `${MODAL} button[aria-label^="Filter by type"]`;
const PANEL = `${MODAL} [data-search-dropdown-panel]`;

const openSearch = async ({ client, json, vault }) => {
  await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:open-node-search`)});`);
  await client.waitFor(`!!document.querySelector(${json(BUTTON)})`, { label: "filter button rendered" });
};

const openFilter = async ({ client, json }) => {
  await client.evaluate(`document.querySelector(${json(BUTTON)}).click(); return true;`);
  await client.waitFor(`!!document.querySelector(${json(PANEL)})`, { label: "panel open" });
};

const snapshot = ({ client, json }) =>
  client.evaluate(`const panel = document.querySelector(${json(PANEL)});
    const button = document.querySelector(${json(BUTTON)});
    return {
      panelOpen: !!panel,
      buttonLabel: button?.getAttribute("aria-label"),
      buttonClass: button?.className,
      clearLabel: panel?.querySelector("button:not([tabindex='-1'])")?.textContent?.trim() ?? null,
      hasTypeSearch: !!panel?.querySelector("input[type=text]"),
      rows: Array.from(panel?.querySelectorAll("input[type=checkbox]") ?? []).map((c) => ({
        name: c.closest("label")?.textContent?.trim(), checked: c.checked })),
      // Normalised markup so before/after runs diff exactly.
      html: panel?.innerHTML.replace(/\\s+/g, " "),
    };`);

export default [
  {
    name: "advanced search filter: initial",
    input: "open node search; click Filter by type",
    expected: "panel open, every row checked, no Clear filter button",
    run: async (ctx) => {
      await openSearch(ctx);
      await openFilter(ctx);
      return snapshot(ctx);
    },
    expect: (a) => ({
      pass: a.panelOpen && a.rows.length > 0 && a.rows.every((r) => r.checked) && a.clearLabel === null,
      actual: `${a.rows.length} rows, all checked=${a.rows.every((r) => r.checked)}, clear=${a.clearLabel}`,
    }),
  },
  {
    name: "advanced search filter: Only",
    input: "open filter; click Only on the first row",
    expected: "panel stays open, one row checked, Clear filter (1), badge on button",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openSearch(ctx);
      await openFilter(ctx);
      await client.evaluate(`document.querySelector(${json(`${PANEL} button[tabindex='-1']`)}).click(); return true;`);
      await client.waitFor(`!!Array.from(document.querySelectorAll(${json(`${PANEL} button`)})).find((b) => b.textContent.startsWith("Clear filter"))`, { label: "clear filter shown" });
      return snapshot(ctx);
    },
    expect: (a) => ({
      pass: a.panelOpen && a.rows.filter((r) => r.checked).length === 1 && a.clearLabel === "Clear filter (1)" && /1 selected/.test(a.buttonLabel),
      actual: `open=${a.panelOpen}, checked=${a.rows.filter((r) => r.checked).length}, clear=${a.clearLabel}, label=${a.buttonLabel}`,
    }),
  },
  {
    name: "advanced search filter: Clear filter",
    input: "Only on first row, then Clear filter",
    expected: "every row checked again, Clear filter gone, plain button label",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openSearch(ctx);
      await openFilter(ctx);
      await client.evaluate(`document.querySelector(${json(`${PANEL} button[tabindex='-1']`)}).click(); return true;`);
      await client.waitFor(`!!Array.from(document.querySelectorAll(${json(`${PANEL} button`)})).find((b) => b.textContent.startsWith("Clear filter"))`, { label: "clear filter shown" });
      await client.evaluate(`Array.from(document.querySelectorAll(${json(`${PANEL} button`)})).find((b) => b.textContent.startsWith("Clear filter")).click(); return true;`);
      await client.waitFor(`!Array.from(document.querySelectorAll(${json(`${PANEL} button`)})).find((b) => b.textContent.startsWith("Clear filter"))`, { label: "clear filter gone" });
      return snapshot(ctx);
    },
    expect: (a) => ({
      pass: a.rows.every((r) => r.checked) && a.clearLabel === null && a.buttonLabel === "Filter by type",
      actual: `all checked=${a.rows.every((r) => r.checked)}, clear=${a.clearLabel}, label=${a.buttonLabel}`,
    }),
  },
];

