// ENG-2478: type filter panel inside the node summoning menu.
const MENU = ".dg-node-summon-menu";
const BUTTON = `${MENU} button[aria-label="Filter by type"]`;
const SCRATCH = "summon-filter-scratch.md";

const arrowDown = { key: "ArrowDown", code: "ArrowDown", windowsVirtualKeyCode: 40, nativeVirtualKeyCode: 40 };
const enter = { key: "Enter", code: "Enter", windowsVirtualKeyCode: 13, nativeVirtualKeyCode: 13 };

// Real mouse events, so the menu's mousedown preventDefault is exercised.
const clickAt = async ({ client }, expr, label) => {
  const r = await client.evaluate(`const el = ${expr}; if (!el) return null;
    const b = el.getBoundingClientRect(); return { x: b.x + b.width / 2, y: b.y + b.height / 2 };`);
  if (!r) throw new Error(`no element: ${label}`);
  for (const type of ["mouseMoved", "mousePressed", "mouseReleased"])
    await client.send("Input.dispatchMouseEvent", { type, x: r.x, y: r.y, button: "left", clickCount: 1 });
};

const q = (json, sel) => `document.querySelector(${json(sel)})`;
const rowLabel = (json, name) =>
  `Array.from(document.querySelectorAll(${json(`${MENU} label`)})).find((l) => l.textContent.trim().startsWith(${json(name)}))`;

const state = ({ client, json }) =>
  client.evaluate(`const menu = ${q(json, MENU)};
    const button = ${q(json, BUTTON)};
    const suggestion = menu?.querySelector(".suggestion");
    return {
      menuOpen: !!menu,
      panelOpen: !!menu?.querySelector("input[type=checkbox]"),
      hasTypeSearch: !!menu?.querySelector("input[type=text]"),
      buttonActive: !!button?.classList.contains("is-active"),
      clearLabel: Array.from(menu?.querySelectorAll("button") ?? []).find((b) => b.textContent.startsWith("Clear filter"))?.textContent.trim() ?? null,
      rows: Array.from(menu?.querySelectorAll("input[type=checkbox]") ?? []).map((c) => ({ name: c.closest("label")?.textContent.trim(), checked: c.checked })),
      groups: Array.from(suggestion?.children ?? []).filter((el) => !el.classList.contains("suggestion-item")).map((el) => el.textContent.trim()),
      items: menu?.querySelectorAll(".suggestion-item").length ?? 0,
      editorFocused: !!document.activeElement?.closest(".cm-content"),
      line: app.workspace.activeLeaf?.view?.editor?.getLine(0),
    };`);

const openMenu = async (ctx) => {
  const { client, json } = ctx;
  const p = await ctx.writeNote(SCRATCH, "\n");
  const trigger = await client.evaluate(`return app.plugins.plugins[${json(ctx.vault.pluginId)}].settings.nodeSearchTrigger;`);
  await client.evaluate(`return (async () => {
    const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(p)}), { state: { mode: "source" } });
    app.workspace.setActiveLeaf(leaf, { focus: true });
    leaf.view.editor.focus();
    leaf.view.editor.setCursor({ line: 0, ch: 0 });
    return true;
  })();`);
  await client.typeText(trigger);
  await client.waitFor(`!!${q(json, BUTTON)}`, { label: "summon menu open" });
  return { p, trigger };
};

const openPanel = async (ctx) => {
  await clickAt(ctx, q(ctx.json, BUTTON), "filter button");
  await ctx.client.waitFor(`!!${q(ctx.json, `${MENU} input[type=checkbox]`)}`, { label: "panel open" });
};

const clickOnly = async (ctx, name) => {
  const { client, json } = ctx;
  // "Only" shows on hover; clicking the row's button directly.
  await clickAt(ctx, `${rowLabel(json, name)}?.parentElement.querySelector("button[tabindex='-1']")`, `Only ${name}`);
};

const clearFilter = (ctx) =>
  clickAt(ctx, `Array.from(document.querySelectorAll(${ctx.json(`${MENU} button`)})).find((b) => b.textContent.startsWith("Clear filter"))`, "Clear filter");

const settle = (ctx) => ctx.client.evaluate(`return new Promise((r) => setTimeout(() => r(true), 150));`);

export default [
  {
    name: "summon filter: opens inline",
    input: "type trigger; click filter button",
    expected: "panel inside menu, menu open, editor focused, all checked, no type search, button active",
    run: async (ctx) => {
      await openMenu(ctx);
      const before = await state(ctx);
      await openPanel(ctx);
      return { before, after: await state(ctx) };
    },
    expect: ({ before, after: a }) => ({
      pass: !before.buttonActive && a.menuOpen && a.panelOpen && a.editorFocused && a.rows.length > 1 &&
        a.rows.every((r) => r.checked) && !a.hasTypeSearch && a.buttonActive && a.clearLabel === null,
      actual: `menu=${a.menuOpen}, panel=${a.panelOpen}, focused=${a.editorFocused}, ${a.rows.length} rows all checked=${a.rows.every((r) => r.checked)}, search=${a.hasTypeSearch}, active=${a.buttonActive}`,
    }),
  },
  {
    name: "summon filter: uncheck removes group",
    input: "open panel; uncheck the first group's type",
    expected: "that group disappears; Clear filter (N-1); others remain",
    run: async (ctx) => {
      await openMenu(ctx);
      await openPanel(ctx);
      const before = await state(ctx);
      const target = before.groups[0];
      await clickAt(ctx, `${rowLabel(ctx.json, target)}?.querySelector("input")`, `checkbox ${target}`);
      await settle(ctx);
      return { target, before, after: await state(ctx) };
    },
    expect: ({ target, before, after: a }) => ({
      pass: !a.groups.includes(target) && a.groups.length === before.groups.length - 1 &&
        a.clearLabel === `Clear filter (${a.rows.length - 1})` && a.editorFocused && a.panelOpen,
      actual: `removed ${target}: ${before.groups.length} → ${a.groups.length} groups, ${a.clearLabel}, focused=${a.editorFocused}`,
    }),
  },
  {
    name: "summon filter: Only collapses panel",
    input: "open panel; Only on the second group's type",
    expected: "panel closes; one group left; button active",
    run: async (ctx) => {
      await openMenu(ctx);
      await openPanel(ctx);
      const target = (await state(ctx)).groups[1];
      await clickOnly(ctx, target);
      await ctx.client.waitFor(`!${q(ctx.json, `${MENU} input[type=checkbox]`)}`, { label: "panel closed" });
      return { target, after: await state(ctx) };
    },
    expect: ({ target, after: a }) => ({
      pass: !a.panelOpen && a.groups.length === 1 && a.groups[0] === target && a.buttonActive && a.activeFirst !== false && a.editorFocused,
      actual: `panel=${a.panelOpen}, groups=${JSON.stringify(a.groups)}, active=${a.buttonActive}, focused=${a.editorFocused}`,
    }),
  },
  {
    name: "summon filter: Clear filter restores all",
    input: "Only on a type; reopen panel; Clear filter (1)",
    expected: "all groups back; every row checked; button not active once panel closes",
    run: async (ctx) => {
      await openMenu(ctx);
      await openPanel(ctx);
      const before = await state(ctx);
      await clickOnly(ctx, before.groups[0]);
      await ctx.client.waitFor(`!${q(ctx.json, `${MENU} input[type=checkbox]`)}`, { label: "panel closed" });
      await openPanel(ctx);
      const clearLabel = (await state(ctx)).clearLabel;
      await clearFilter(ctx);
      await settle(ctx);
      const afterClear = await state(ctx);
      await clickAt(ctx, q(ctx.json, BUTTON), "close panel");
      await settle(ctx);
      return { before, clearLabel, afterClear, closed: await state(ctx) };
    },
    expect: ({ before, clearLabel, afterClear, closed }) => ({
      pass: clearLabel === "Clear filter (1)" && afterClear.rows.every((r) => r.checked) &&
        JSON.stringify(closed.groups) === JSON.stringify(before.groups) && !closed.buttonActive,
      actual: `${clearLabel} → all checked=${afterClear.rows.every((r) => r.checked)}, groups ${closed.groups.length}/${before.groups.length}, active=${closed.buttonActive}`,
    }),
  },
  {
    name: "summon filter: uncheck all shows all",
    input: "open panel; uncheck every type one by one",
    expected: "every row checked again; all groups shown",
    run: async (ctx) => {
      await openMenu(ctx);
      await openPanel(ctx);
      const before = await state(ctx);
      for (const row of before.rows) {
        await clickAt(ctx, `${rowLabel(ctx.json, row.name)}?.querySelector("input")`, `checkbox ${row.name}`);
        await settle(ctx);
      }
      return { before, after: await state(ctx) };
    },
    expect: ({ before, after: a }) => ({
      pass: a.rows.every((r) => r.checked) && JSON.stringify(a.groups) === JSON.stringify(before.groups) && a.clearLabel === null,
      actual: `all checked=${a.rows.every((r) => r.checked)}, groups ${a.groups.length}/${before.groups.length}, clear=${a.clearLabel}`,
    }),
  },
  {
    name: "summon filter: typing narrows within filter",
    input: "Only on a type; type 3 letters of one of its titles",
    expected: "text lands in the editor; only that type's group; items narrowed",
    run: async (ctx) => {
      const { trigger } = await openMenu(ctx);
      await openPanel(ctx);
      const target = (await state(ctx)).groups[0];
      await clickOnly(ctx, target);
      await ctx.client.waitFor(`!${q(ctx.json, `${MENU} input[type=checkbox]`)}`, { label: "panel closed" });
      const filtered = await state(ctx);
      const title = await ctx.client.evaluate(`return ${q(ctx.json, `${MENU} .suggestion-item`)}.textContent.trim();`);
      const typed = title.slice(0, 3);
      await ctx.client.typeText(typed);
      await settle(ctx);
      return { trigger, typed, target, filtered, after: await state(ctx) };
    },
    expect: ({ trigger, typed, target, filtered, after: a }) => ({
      pass: a.line === `${trigger}${typed}` && a.groups.length === 1 && a.groups[0] === target && a.items >= 1 && a.items <= filtered.items,
      actual: `line="${a.line}", groups=${JSON.stringify(a.groups)}, items ${filtered.items} → ${a.items}`,
    }),
  },
  {
    name: "summon filter: resets on reopen",
    input: "Only on a type; Escape; type trigger again",
    expected: "menu closes on Escape; reopened menu shows all groups, button not active",
    run: async (ctx) => {
      const { trigger } = await openMenu(ctx);
      await openPanel(ctx);
      const before = await state(ctx);
      await clickOnly(ctx, before.groups[0]);
      await ctx.client.waitFor(`!${q(ctx.json, `${MENU} input[type=checkbox]`)}`, { label: "panel closed" });
      await ctx.client.pressEscape();
      await ctx.client.waitFor(`!${q(ctx.json, MENU)}`, { label: "menu closed" });
      await ctx.client.typeText(" " + trigger);
      await ctx.client.waitFor(`!!${q(ctx.json, BUTTON)}`, { label: "menu reopened" });
      return { before, after: await state(ctx) };
    },
    expect: ({ before, after: a }) => ({
      pass: JSON.stringify(a.groups) === JSON.stringify(before.groups) && !a.buttonActive,
      actual: `groups ${a.groups.length}/${before.groups.length}, active=${a.buttonActive}`,
    }),
  },
  {
    name: "summon filter: keys work with panel open",
    input: "open panel; ArrowDown; Enter",
    expected: "second result inserted as a link; menu closed",
    run: async (ctx) => {
      await openMenu(ctx);
      await openPanel(ctx);
      const second = await ctx.client.evaluate(`return document.querySelectorAll(${ctx.json(`${MENU} .suggestion-item`)})[1]?.textContent.trim();`);
      await ctx.client.key(arrowDown);
      await ctx.client.key(enter);
      await ctx.client.waitFor(`!${q(ctx.json, MENU)}`, { label: "menu closed" });
      return { second, after: await state(ctx) };
    },
    expect: ({ second, after: a }) => ({
      pass: !a.menuOpen && !!second && a.line.includes(second),
      actual: `line="${a.line}", expected to contain "${second}"`,
    }),
  },
];

